// YOUR OFFER BRIEF - who you are, what you sell, whom to target. It drives the search targeting (node 1), the
// decision-maker choice and fit score (node 9) and the personalised email (node 10).
// Paste the contents of offer.md between the backticks. Free text is fine; optional "## Target healthcare types",
// "## Target areas" and "## Target decision makers" bullet sections are parsed into lists (see offer.example.md).
// Lines containing TODO and <!-- html comments --> are ignored. Empty brief = generic emails, no fit score.
// n8n Cloud cannot read local files - to keep the brief elsewhere, fetch it with an HTTP Request node (e.g. a raw
// GitHub / Google Docs export URL) placed before this one and replace OFFER_MARKDOWN with $json.data.
const OFFER_MARKDOWN = `
Act as a B2B sales outreach specialist for Daffodil Software Ltd., a Bangladesh-based software and digital-transformation company established in 2001.

Write a concise, personalized cold email to a healthcare organization.

About Daffodil Software:

- We develop custom software, hospital-management systems, ERP, mobile apps, AI applications, cloud solutions, cybersecurity/SOC services, and software integrations.
- Our healthcare solutions can unify patient records, appointments, billing, pharmacy, laboratory workflows, reporting, and operational analytics.
- We help healthcare organizations reduce manual work, improve data accuracy, speed up patient service, and gain visibility across operations.
- We can customize solutions around the hospital’s existing workflows and integrate with its current systems.

Prospect details:

- Organization: [Hospital/clinic/diagnostic-centre name]
- Recipient: [Name and job title]
- Location: [City/country]
- Known challenge, service, technology, or recent news: [Detail]
- Desired call to action: [15–20 minute discovery call]

Requirements:

1. Write a specific subject line under 8 words.
2. Open with a genuine personalized observation—not generic praise.
3. Mention only the most relevant 1–2 Daffodil capabilities.
4. Clearly explain a likely operational outcome for this organization.
5. Avoid exaggerated claims, jargon, and long feature lists.
6. Keep the email below 140 words.
7. End with a low-pressure meeting request.
8. Include this signature:
   [Sender Name]
   [Title] | Daffodil Software Ltd.
   <software@daffodil-bd.com> | +8801713493026
   <https://daffodilsoft.com/>

about comapnies :

Daffodil Software Ltd. is a Bangladesh-based software development and digital-transformation company, established in 2001. It serves Bangladesh and international markets including the USA, UAE, and Malaysia, and positions itself as an official Odoo Partner with 42+ professionals. Its office is in Dhanmondi, Dhaka. Company profile
For lead generation, their strongest buyer profiles are organizations needing operational software: education institutions, hospitals, corporate businesses, retailers, manufacturers, finance, pharmaceutical firms, hospitality businesses, clubs, and event organizers. They show particular depth in education, healthcare, and ERP-led business automation. Official site
Their services:

- Custom software and AI application development
- Web, e-commerce, and mobile-app development
- ERP consulting, implementation, and Odoo customization
- IT outsourcing; IT infrastructure, cloud migration, and managed services
- Cybersecurity monitoring / SOC-as-a-Service
- Software-testing certification and quality assurance
- System integration, APIs, data migration, and cloud deployment
Their ready-made products include business ERP/CRM, hospital management, school and university management, HR/payroll, AI education tools, AI lead/support automation, club ERP, campus payment/access cards, virtual-event management, study-abroad management, and restaurant ERP.
Useful outreach angles:
- “Replace disconnected spreadsheets and tools with a unified ERP/CRM.”
- “Modernize university, school, or hospital operations with a purpose-built platform.”
- “Deploy Odoo with custom workflows, integrations, and local implementation support.”
- “Use AI to automate customer conversations, lead qualification, HR, or learning workflows.”
- “Build a secure custom web/mobile product without hiring a full internal engineering team.”
Public contact: <software@daffodil-bd.com> · +880 1713-493026.

Daffodil Software’s products include:

- Smart Business 24 — ERP for accounting, inventory, CRM, HR, supply chain, and analytics
- Smart Hospital — hospital management for patient records, appointments, billing, pharmacy, and laboratory
- Eduvas School — school-management system
- Eduvas University — university operations and administration platform
- Smart HR — SaaS HR platform for recruitment, payroll, attendance, performance, and analytics
- AI Professor — AI education assistant for quizzes, assignments, grading, course support, and learning content
- Central AI — AI chat/lead-management platform for web, WhatsApp, Facebook, Instagram, CRM, and Odoo
- AI HR Management — AI-enabled HR automation and workforce-planning platform
- Club ERP — membership, accounting, events, guest management, and communication for clubs
- IUMS — integrated university-management system
- Study Abroad — management platform for international education consultancies
- 1 Card — campus payments, access control, attendance, and library management
- Virtual Gate — virtual-event platform for registration, tickets, booths, networking, and analytics
- Smart Hospitality OS — restaurant ERP for sales, operations, staff, and business intelligence
`;
const MAX_CHARS = 6000;   // keeps every AI call affordable - shorten the brief rather than raise this
const MIN_FIT_ALERT = 0;  // per-lead Telegram alerts only for Fit Score >= this (0 = alert on every lead); the run summary is always sent

const HEADING = /^\s{0,3}#{1,6}\s+(.*?)\s*#*\s*$/;
const BULLET = /^\s*(?:[-*+]|\d+[.)])\s+(.*\S)\s*$/;
const lines = OFFER_MARKDOWN.replace(/<!--[\s\S]*?-->/g, '').split('\n').filter(l => !/TODO/.test(l));
const hasOffer = lines.some(l => l.trim() && !HEADING.test(l));
let text = lines.join('\n').trim();
if (text.length > MAX_CHARS) text = text.slice(0, MAX_CHARS);

// {heading: [lines]} - the three "Target ..." sections become lists
const sections = { '': [] };
let current = '';
for (const line of text.split('\n')) {
  const m = line.match(HEADING);
  if (m) { current = m[1].trim(); sections[current] = sections[current] || []; }
  else sections[current].push(line);
}
const shortTerm = (s) => s.split(/\s+[-–—:]\s+|\s*\(/)[0].trim();     // 'hospital (private)' -> 'hospital'
const bullets = (ls) => ls.map(l => l.match(BULLET)).filter(Boolean).map(m => shortTerm(m[1]));
const pick = (re) => { for (const [h, ls] of Object.entries(sections)) if (re.test(h)) return bullets(ls); return []; };
const targetTypes = hasOffer ? pick(/target (healthcare )?(types|customers|segments)|ideal customer/i) : [];
const targetAreas = hasOffer ? pick(/target (areas|locations)/i) : [];
const targetTitles = hasOffer ? pick(/target (decision makers|titles|roles|buyers)|decision makers we want/i) : [];

const named = text.match(/^\s*[-*]?\s*(?:company\s*)?name\s*:\s*(.+)$/im)
  || text.match(/(?:for|on behalf of|represent(?:ing)?)\s+((?:[A-Z][\w&.\-]*\s+){0,4}(?:Ltd|Limited|Inc|LLC|PLC|Co)\.?)/);
const companyName = hasOffer && named ? named[1].trim().replace(/\.$/, '') : '';

const titles = targetTitles.join(', ')
  || 'the commercial decision maker (Managing Director, CEO, Chairman, Head of Procurement / IT / Operations or similar)';
const profileBlock = `\n--- OFFER PROFILE ---\n${text}\n--- END OFFER PROFILE ---`;

// Appended to node 9's system prompt (extraction + fit) and node 10's (email). Keep in sync with lead_generator.py.
const extractorContext = !hasOffer ? '' :
  ` OFFER PROFILE - you research on behalf of the company described below. When the site names several people, prefer decision makers with these titles: ${titles}. ` +
  `Add fit_score ('1'-'5': how well this organisation matches the profile's target customers and could use its products or services) and fit_reason ` +
  `(one sentence citing concrete evidence from their site - e.g. manual booking, no patient portal, many departments, multiple branches).` + profileBlock;

const writerContext = !hasOffer ? '' :
  ` OFFER PROFILE - you write on behalf of the company described below. Open with ONE specific observation about this organisation ` +
  `(a named service, department, branch, accreditation, technology or scale from the website excerpt), connect it to the ONE or TWO capabilities from the profile ` +
  `that fit best and state the likely operational outcome for them, close with the profile's call to action and use its signature. ` +
  `Follow the profile's own writing requirements (length, subject line, tone) wherever they differ from the defaults above; treat bracketed placeholders ` +
  `such as [Name] or [Detail] as slots to fill from the lead data and leave sender placeholders like [Sender Name] exactly as written. ` +
  `Never open with 'I hope this message finds you well' or similar filler; no generic praise.` + profileBlock;

return [{ json: { hasOffer, companyName, targetTypes, targetAreas, targetTitles, offerText: text, extractorContext, writerContext, minFitAlert: MIN_FIT_ALERT } }];

// Builds ~30 search queries per run (area x category, shuffled) and emits each one for two search engines,
// so there is a large enough candidate pool to end up with 50 NEW leads after de-duplication. Edit the lists below to retarget.
const defaultAreas = [
  'Dhanmondi', 'Gulshan', 'Banani', 'Uttara', 'Mirpur', 'Mohakhali', 'Panthapath', 'Motijheel',
  'Bashundhara', 'Badda', 'Tejgaon', 'Malibagh', 'Shyamoli', 'Mohammadpur', 'Wari', 'Khilgaon'
];
const defaultCategories = [
  'hospital', 'diagnostic center', 'clinic', 'pharmaceutical company', 'medical equipment supplier',
  'dental clinic', 'eye hospital', 'physiotherapy center', 'maternity hospital', 'medical college hospital'
];
// The offer brief (node 0) can narrow the targeting: its "Target areas" / "Target healthcare types" lists win
const offer = $('0. Offer Profile').first().json;
const areas = offer.targetAreas && offer.targetAreas.length ? offer.targetAreas : defaultAreas;
const categories = offer.targetTypes && offer.targetTypes.length ? offer.targetTypes : defaultCategories;

const generalQueries = [
  'list of private hospitals in Dhaka Bangladesh contact',
  'top diagnostic centers in Dhaka contact email',
  'pharmaceutical companies head office Dhaka Bangladesh contact',
  'medical equipment importers Dhaka Bangladesh contact'
];
const MAX_QUERIES = 30;

const combos = [];
for (const area of areas) {
  for (const category of categories) {
    combos.push(`${category} in ${area} Dhaka contact email phone`);
  }
}

// Fisher-Yates shuffle: each run explores different area/category combinations and surfaces new leads
for (let i = combos.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [combos[i], combos[j]] = [combos[j], combos[i]];
}

const queries = [...generalQueries, ...combos.slice(0, MAX_QUERIES - generalQueries.length)];

// Every query is sent to BOTH engines (node 2 fetches one URL per item). Bing is read through its RSS output
// (&format=rss: plain XML, direct target links) and returns the facility's own website far more often than
// DuckDuckGo, which leans towards directory sites. If one engine throttles automated traffic the other keeps going.
const bingUrl = (q) => `https://www.bing.com/search?q=${encodeURIComponent(q)}&format=rss&cc=BD&setlang=en`;
const ddgUrl = (q) => `https://html.duckduckgo.com/html/?q=${encodeURIComponent(q)}`;

const out = [];
for (const query of queries) {
  out.push({ json: { query, engine: 'bing', url: bingUrl(query) } });
  out.push({ json: { query, engine: 'duckduckgo', url: ddgUrl(query) } });
}
return out;

// Parse search responses into { title, snippet, url, domain, source } items. Node 2 fetched one Bing RSS feed
// and one DuckDuckGo HTML page per query (auto-detected here by markup), so the pool is bigger and the run
// survives one engine throttling automated traffic.
//   Bing RSS:   <item><title>..</title><link>direct url</link><description>..</description></item>
//   DuckDuckGo: <a class="result__a" href="...">Title</a> ... <a class="result__snippet" ...>Snippet</a>
const decodeEntities = (s) => (s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#x27;|&#39;|&apos;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const SKIP_DOMAINS = [
  // search engines / social networks / Q&A
  'duckduckgo.com', 'bing.com', 'microsoft.com', 'google.com', 'facebook.com', 'wikipedia.org', 'youtube.com',
  'linkedin.com', 'instagram.com', 'twitter.com', 'x.com', 'quora.com', 'reddit.com', 'pinterest.com',
  // directories / aggregators: they list companies but are not the company itself
  'yelp.com', 'tripadvisor.com', 'justdial.com', 'yellowpages.com', 'mawbiz.com.bd', 'dhanmondi.bd',
  'businesslist.com.bd', 'bdtradeinfo.com', 'cybo.com', 'yellowpagesbd.com', 'bangladeshyellowpages.com',
  'medex.com.bd', 'doctorola.com', 'sasthyaseba.com', 'bdhospitals.com', 'hospitalsbd.com', 'kagoz.com',
  'bestinmeds.com', 'infoisinfo.com.bd', 'deho.ai', 'khojkorun.com', 'doctorbd24.com', 'doctorbangladesh.com',
  'investbangladesh.gov.bd'
];
const DIRECTORY_HINT = /yellowpage|directory|listing|bizlist|businesslist|\.blogspot\.|wordpress\.com/i;
// A Dhaka healthcare lead mentions the city / country or lives on a .bd domain. Anything else is off-topic - or one
// of the unrelated cached pages Bing serves when it suspects a bot - and is dropped before we scrape it.
const RELEVANT = /dhaka|bangladesh|\.bd\b|\bbd\b/i;
// "Top 10 ...", "... - Verified List", "Doctors List", "... Directory" are aggregator pages, not a facility
// Blog / guide articles ("Maternity Leave in Bangladesh: Rules, Benefits") and government portals that are not care providers
const ARTICLE_TITLE = /:\s*(rules|guide|benefits|tips|how|what|why|everything)|^(how|what|why|when)\b|\b(guide|tips|explained)\b/i;
const HEALTHCARE_HINT = /hospital|medical|health|clinic|diagnos|pharma|dental|physio|eye|maternity|cardiac/i;
const AGGREGATOR_TITLE = /\b(top|best)\s+\d+\b|\blists?\b|\blistings?\b|directory|\bnear me\b|^(top|best|leading)\b[^|]*?\b[a-z]+s\s+in\s+(dhaka|bangladesh)/i;   // "Best Hospitals in Dhaka" = a list

const isSkippedDomain = (domain) => !domain
  || SKIP_DOMAINS.some(d => domain === d || domain.endsWith('.' + d))
  || DIRECTORY_HINT.test(domain);

// DDG wraps outbound links as //duckduckgo.com/l/?uddg=<encoded target>&rut=...
const unwrapDdg = (href) => {
  let url = href.replace(/&amp;/g, '&').trim();
  if (url.startsWith('//')) url = 'https:' + url;
  if (url.includes('uddg=')) {
    try { url = new URL(url).searchParams.get('uddg') || url; } catch (e) {}
  }
  return url;
};

const results = [];
const push = (rawTitle, rawSnippet, url, source) => {
  let domain;
  try { domain = new URL(url).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return; }
  if (isSkippedDomain(domain)) return;
  const title = decodeEntities(rawTitle), snippet = decodeEntities(rawSnippet);
  if (!RELEVANT.test(`${title} ${snippet} ${url}`) || AGGREGATOR_TITLE.test(title) || ARTICLE_TITLE.test(title)) return;
  if (domain.endsWith('.gov.bd') && !HEALTHCARE_HINT.test(`${title} ${snippet} ${url}`)) return;   // ministry / investment portal
  results.push({ json: { title, snippet, url, domain, source } });
};

const rssItem = /<item>[\s\S]*?<title>([\s\S]*?)<\/title>[\s\S]*?<link>([\s\S]*?)<\/link>[\s\S]*?<description>([\s\S]*?)<\/description>/g;
const ddgResult = /<a[^>]*class="result__a"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>[\s\S]*?<a[^>]*class="result__snippet"[^>]*>([\s\S]*?)<\/a>/g;

for (const item of $input.all()) {
  const body = typeof item.json.data === 'string' ? item.json.data : '';
  let match;
  if (body.includes('<item>')) {
    while ((match = rssItem.exec(body)) !== null) push(match[1], match[3], decodeEntities(match[2]), 'bing');
  } else {
    while ((match = ddgResult.exec(body)) !== null) push(match[2], match[3], unwrapDdg(match[1]), 'duckduckgo');
  }
}

// Curated fallback so the pipeline still produces output when both search engines block automated traffic
if (results.length < 5) {
  const backupLeads = [
    { title: "Labaid Diagnostic Center Dhanmondi", snippet: "Managing Director: Dr. AM Shamim. Contact: info@labaidgroup.com", url: "https://labaid.com.bd", domain: "labaid.com.bd", source: "curated" },
    { title: "Popular Diagnostic Centre Gulshan", snippet: "Managing Director: Dr. Mustafizur Rahman. Email: info@populardiagnostic.com", url: "https://populardiagnostic.com", domain: "populardiagnostic.com", source: "curated" },
    { title: "Ibn Sina Hospital Dhanmondi", snippet: "Managing Director: Prof. Dr. Sadrul Islam. Contact: info@ibnsinatrust.com", url: "https://ibnsinatrust.com", domain: "ibnsinatrust.com", source: "curated" },
    { title: "Square Hospitals Panthapath", snippet: "CEO: Mr. Esam Ebne Yousuf. Email: info@squarehospital.com", url: "https://squarehospital.com", domain: "squarehospital.com", source: "curated" },
    { title: "Prescription Point Banani", snippet: "Chairman: Dr. Md. Abdul Majid. Contact: info@ppointbd.com", url: "https://ppointbd.com", domain: "ppointbd.com", source: "curated" },
    { title: "Evercare Hospital Dhaka Bashundhara", snippet: "MD & CEO: Dr. Ratnadeep Chaskar. Contact: info.dhaka@evercarebd.com", url: "https://evercarebd.com", domain: "evercarebd.com", source: "curated" },
    { title: "United Hospital Gulshan 2", snippet: "Managing Director: Mr. Faridur Rahman. Contact: info@uhlbd.com", url: "https://uhlbd.com", domain: "uhlbd.com", source: "curated" },
    { title: "Asgar Ali Hospital Gendaria", snippet: "CEO: Prof. Dr. Zabrul SM. Email: info@asgaralihospital.com", url: "https://asgaralihospital.com", domain: "asgaralihospital.com", source: "curated" },
    { title: "BRB Hospital Panthapath", snippet: "Managing Director: Mr. Mozibar Rahman. Email: info@brbhospital.com", url: "https://brbhospital.com", domain: "brbhospital.com", source: "curated" },
    { title: "Incepta Pharmaceuticals Tejgaon", snippet: "Managing Director: Mr. Abdul Muktadir. Email: info@inceptapharma.com", url: "https://inceptapharma.com", domain: "inceptapharma.com" }
  ];

  for (const item of backupLeads) {
    results.push({ json: item });
  }
}

return results;

// Runs once. Input = the Overpass API answer from node 1b (or an error item when the API is unreachable).
// Output = one candidate per facility that has a website, in the same shape node 3 emits, plus the structured
// details OpenStreetMap already knows (phone, email, address, type) so nodes 8-11 can reuse them as verified facts.
const TYPE_LABELS = {
  hospital: 'Hospital', clinic: 'Clinic', doctors: 'Doctors Chamber / Medical Practice', dentist: 'Dental Clinic',
  pharmacy: 'Pharmacy', laboratory: 'Diagnostic Laboratory', centre: 'Healthcare Centre',
  physiotherapist: 'Physiotherapy Center', optometrist: 'Eye Care / Optometry', blood_donation: 'Blood Bank',
  rehabilitation: 'Rehabilitation Center', birthing_centre: 'Maternity Center'
};
// Keep in sync with node 1 - used to derive the area from the address (OSM rarely fills addr:suburb in Dhaka)
const AREAS = [
  'Dhanmondi', 'Gulshan', 'Banani', 'Uttara', 'Mirpur', 'Mohakhali', 'Panthapath', 'Motijheel',
  'Bashundhara', 'Badda', 'Tejgaon', 'Malibagh', 'Shyamoli', 'Mohammadpur', 'Wari', 'Khilgaon'
];
const SOCIAL = /facebook\.com|instagram\.com|linkedin\.com|youtube\.com|twitter\.com|^x\.com$/i;

const results = [];
for (const item of $input.all()) {
  const elements = Array.isArray(item.json.elements) ? item.json.elements : [];
  for (const el of elements) {
    const t = el.tags || {};
    const tag = (k) => { const v = (t[k] || '').trim(); return /^n\/a$/i.test(v) ? '' : v; };

    let website = tag('website') || tag('contact:website');
    const name = tag('name:en') || tag('name');
    if (!website || !name) continue;
    if (!/^https?:\/\//i.test(website)) website = 'https://' + website;
    let domain;
    try { domain = new URL(website).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { continue; }
    if (!domain || SOCIAL.test(domain)) continue;          // a Facebook page tagged as the website is not a lead site

    const type = TYPE_LABELS[tag('healthcare') || tag('amenity')] || 'Healthcare Provider';
    const street = [tag('addr:housenumber'), tag('addr:street')].filter(Boolean).join(' ');
    const address = tag('addr:full') || [street, tag('addr:suburb'), tag('addr:city') || 'Dhaka', tag('addr:postcode')].filter(Boolean).join(', ');
    const location = AREAS.find(a => address.toLowerCase().includes(a.toLowerCase())) || tag('addr:suburb') || 'Dhaka';
    const phone = tag('phone') || tag('contact:phone') || tag('phone:mobile');
    const email = tag('email') || tag('contact:email');
    const snippet = ['OpenStreetMap record', type, address, phone && 'Phone ' + phone, email && 'Email ' + email].filter(Boolean).join(' · ');

    results.push({ json: {
      title: name, snippet, url: website, domain, source: 'openstreetmap',
      known_type: type, known_location: location, known_address: address, known_phone: phone, known_email: email
    } });
  }
}
return results;

// Runs once. Input = rows already in the Google Sheet (or one empty/error item when the sheet is empty
// or unreachable). Candidates come from node 4. Output = up to LIMIT leads whose website is NOT in the sheet yet.
const LIMIT = 50;

const toDomain = (value) => {
  if (!value) return '';
  const raw = String(value).trim();
  try {
    return new URL(/^https?:\/\//i.test(raw) ? raw : 'https://' + raw).hostname.replace(/^www\./, '').toLowerCase();
  } catch (e) {
    return raw.replace(/^https?:\/\//i, '').replace(/^www\./, '').split('/')[0].toLowerCase();
  }
};

const known = new Set();
for (const row of $input.all()) {
  const domain = toDomain(row.json['Website']);
  if (domain) known.add(domain);
}

const fresh = [];
for (const item of $('4. Remove Duplicates (this run)').all()) {
  const domain = toDomain(item.json.domain || item.json.url);
  if (!domain || known.has(domain)) continue;
  known.add(domain);
  fresh.push({ json: { ...item.json, domain } });
  if (fresh.length >= LIMIT) break;
}

return fresh;

// Runs once for all items. Input = homepage responses from node 7 (one per lead, errors included), paired by
// index with the leads from node 6. For each lead this node:
//   1. cleans the homepage text,
//   2. follows up to 3 same-site executive pages ("Message from Chairman / Managing Director / CEO", board, management,
//      about) plus the contact page - in Bangladesh the executives' names sit on those pages, signed at the bottom,
//   3. pulls emails, phones, LinkedIn and Facebook links out of the raw HTML,
// so the OpenAI step gets every signal available.
const leads = $('6. Skip Known Leads & Limit to 50').all();
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36';
const MAX_EXTRA_PAGES = 4;   // up to 3 executive / management pages + the contact page
const MAX_PEOPLE_PAGES = 3;
const CONCURRENCY = 5;

// n8n exposes an HTTP helper inside Code nodes; if it is missing we simply skip the extra pages.
const http = (() => {
  try { if (this && this.helpers && typeof this.helpers.httpRequest === 'function') return this.helpers; } catch (e) {}
  try { if (typeof helpers !== 'undefined' && helpers && typeof helpers.httpRequest === 'function') return helpers; } catch (e) {}
  return null;
})();

const decodeEntities = (s) => (s || '')
  .replace(/&amp;/g, '&')
  .replace(/&nbsp;/g, ' ')
  .replace(/&quot;/g, '"')
  .replace(/&#x27;|&#39;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>');

const htmlToText = (html) => decodeEntities((html || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' '))
  .replace(/\s+/g, ' ')
  .trim();

const unique = (arr) => [...new Set(arr)];

const extractSignals = (html) => {
  const text = decodeEntities(html || '');
  const emails = unique([
    ...(text.match(/href=["']mailto:([^"'?]+)/gi) || []).map(m => m.replace(/href=["']mailto:/i, '')),
    ...(text.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi) || [])
  ].map(e => e.trim().toLowerCase()))
    .filter(e => !/\.(png|jpe?g|gif|svg|webp|css|js)$/.test(e) && !/example\.|sentry\.|wixpress|yourdomain|domain\.com|email\.com/.test(e));

  const phones = unique([
    ...(text.match(/href=["']tel:([^"']+)/gi) || []).map(m => m.replace(/href=["']tel:/i, '')),
    ...(text.match(/(?:\+?880|0)?[\s-]?1[3-9]\d{2}[\s-]?\d{3}[\s-]?\d{3}\b/g) || []),        // BD mobile
    ...(text.match(/(?:\+?880|0)?[\s-]?2[\s-]?\d{4}[\s-]?\d{3,4}\b/g) || []),                // Dhaka landline
    ...(text.match(/\b1[06]\d{3}\b/g) || [])                                                 // 5-digit hotlines
  ].map(p => p.trim()));

  const linkedin = unique((text.match(/https?:\/\/(?:[a-z]{2,3}\.)?linkedin\.com\/(?:in|company)\/[a-z0-9_%.-]+/gi) || []));
  const facebook = unique((text.match(/https?:\/\/(?:www\.|m\.)?(?:facebook|fb)\.com\/[a-z0-9_.-]+/gi) || [])
    .filter(u => !/\/(sharer|share|plugins|dialog|login|tr\b)/i.test(u)));

  return { emails: emails.slice(0, 10), phones: phones.slice(0, 10), linkedin: linkedin.slice(0, 5), facebook: facebook.slice(0, 3) };
};

// Digital-maturity checks on the prospect's own site: hard evidence for the fit score and a specific email opener
// ("your site still takes appointments by phone only ..."). Keep in sync with lead_generator.py.
const FEATURE_CHECKS = [
  ['online appointment booking', /href=["'][^"']*(?:appointment|booking|book-now)|online appointment|book (?:an )?appointment online|appointment form/i],
  ['online reports / patient portal', /patient portal|online report|report download|download (?:your |lab )?reports?|view (?:your )?reports? online|e-?reports?\b|report portal/i],
  ['mobile app', /play\.google\.com|apps\.apple\.com|app store|google play|download (?:our|the) app/i],
  ['telemedicine / video consultation', /telemedicine|tele-?health|video consult|online consult(?:ation)?|virtual consult/i],
  ['online payment', /bkash|nagad|sslcommerz|online payment|pay online|pay now/i],
  ['live chat / WhatsApp', /wa\.me\/|whatsapp|tawk\.to|livechat|live chat|m\.me\//i]
];
const TECH_CHECKS = [
  ['WordPress', /wp-content|wp-includes|content=["']WordPress/i], ['Wix', /wixstatic|wix\.com|_wix/i], ['Joomla', /joomla/i],
  ['Drupal', /drupal/i], ['Blogger', /blogger\.com|blogspot/i], ['Squarespace', /squarespace/i],
  ['React / Next.js', /__NEXT_DATA__|\/_next\/|data-reactroot/i], ['Angular', /ng-version/i], ['Laravel', /laravel_session/i],
  ['ASP.NET', /__VIEWSTATE|\.aspx\b/i], ['PHP', /\.php\b/i]
];
// (?<!\d) keeps the tail of a phone number ("...896433 DEPARTMENTS") from being read as a count
const COUNT_CHECKS = [
  ['beds', /(?<!\d)(\d{2,4})\s*[-+]?\s*(?:bedded|beds?)\b/gi], ['branches', /(?<!\d)(\d{1,3})\s*\+?\s*branches/gi],
  ['doctors', /(?<!\d)(\d{2,4})\s*\+?\s*(?:doctors|consultants|physicians|specialists)/gi], ['departments', /(?<!\d)(\d{1,3})\s*\+?\s*departments/gi]
];
const COPYRIGHT = /(?:©|&copy;|copyright)[^0-9<]{0,40}(?:(?:19|20)\d\d\s*[-–]\s*)?((?:19|20)\d\d)/gi;

const extractWebsiteSignals = (html, url) => {
  const page = decodeEntities(html || '');
  if (!page) return { summary: '', present: [], missing: [] };
  const text = htmlToText(page);
  const present = FEATURE_CHECKS.filter(([, re]) => re.test(page)).map(([label]) => label);
  const missing = FEATURE_CHECKS.map(([label]) => label).filter(l => !present.includes(l));
  const tech = TECH_CHECKS.filter(([, re]) => re.test(page)).map(([label]) => label).slice(0, 3);
  const parts = FEATURE_CHECKS.map(([label]) => `${label}: ${present.includes(label) ? 'yes' : 'no'}`);
  parts.push(`tech: ${tech.length ? tech.join(', ') : 'unknown'}`);
  for (const [label, re] of COUNT_CHECKS) {
    const nums = [...text.matchAll(re)].map(m => parseInt(m[1], 10)).filter(n => n < 10000);
    if (nums.length) parts.push(`${label}: ${Math.max(...nums)}`);
  }
  const years = [...page.matchAll(COPYRIGHT)].map(m => parseInt(m[1], 10));
  if (years.length) {
    const latest = Math.max(...years);
    parts.push(`copyright year: ${latest}${latest < new Date().getFullYear() - 1 ? ' (site looks unmaintained)' : ''}`);
  }
  parts.push(`https: ${/^https:\/\//i.test(url || '') ? 'yes' : 'no'}`);
  return { summary: parts.join('; '), present, missing };
};

// Rank same-site links: executive messages (3) > board / management / leadership (2) > about (1); skip department,
// service and doctor-directory pages ("/department/pain-management" is not a management page) and pick the contact page.
const LINK_SCORES = [
  [3, /message|speech|desk[-_ ]of|chairman|managing[-_ ]?director|\bmd\b|\bceo\b|founder/i],
  [2, /board|management|leadership|our[-_ ]?team|directors|executives|administration|governing/i],
  [1, /about|profile|who[-_ ]we[-_ ]are|overview/i]
];
const NEGATIVE_LINK = /\/(departments?|services?|treatments?|packages?|doctors?|consultants?|news|events?|gallery|blog|careers?|jobs?)\/|\/dr-|appointment|login|register|\.(xml|json)$/i;
const CONTACT = /contact/i;
const findExtraLinks = (html, baseUrl) => {
  let baseHost;
  try { baseHost = new URL(baseUrl).hostname.replace(/^www\./, ''); } catch (e) { return []; }
  const people = new Map(), contact = [];
  const linkRegex = /<a[^>]+href=["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = linkRegex.exec(html || '')) !== null) {
    let u;
    try { u = new URL(m[1], baseUrl); } catch (e) { continue; }
    if (u.hostname.replace(/^www\./, '') !== baseHost) continue;
    if (/\.(pdf|jpe?g|png|gif|zip|docx?)$/i.test(u.pathname)) continue;
    u.hash = '';
    if (u.href.replace(/\/$/, '') === baseUrl.replace(/\/$/, '')) continue;
    const haystack = u.pathname + ' ' + htmlToText(m[2]);
    if (CONTACT.test(haystack)) { if (!contact.includes(u.href)) contact.push(u.href); continue; }
    if (NEGATIVE_LINK.test(haystack)) continue;
    const score = Math.max(0, ...LINK_SCORES.filter(([, re]) => re.test(haystack)).map(([s]) => s));
    if (score > (people.get(u.href) || 0)) people.set(u.href, score);
  }
  const ranked = [...people.entries()].sort((a, b) => b[1] - a[1]).map(([url]) => url);
  return [...ranked.slice(0, MAX_PEOPLE_PAGES), ...contact.slice(0, 1)].slice(0, MAX_EXTRA_PAGES);
};

// Text around every executive title on the fetched pages - the exact evidence the AI needs, whatever got truncated.
// Same title list as lead_generator.py (longest first so "Founding Chairman" wins over "Chairman").
const EXEC_TITLES = ['Founder & Managing Director', 'Founder and Managing Director', 'Chairman & Managing Director', 'Chairman and Managing Director',
  'Deputy Managing Director', 'Managing Director', 'MD & CEO', 'Chief Executive Officer', 'CEO', 'Founder & Chairman', 'Founding Chairman',
  'Chairman', 'Vice Chairman', 'Chief Operating Officer', 'Executive Director', 'Director General', 'Medical Director', 'Chief Medical Officer',
  'Director of Operations', 'Director Operations', 'Director (Hospital)', 'Head of Operations', 'General Manager', 'Chief Information Officer',
  'Head of IT', 'IT Manager', 'Head of Procurement', 'Procurement Manager'];
const EXEC_TITLE_RE = new RegExp('(?<![A-Za-z])(' + EXEC_TITLES.sort((a, b) => b.length - a.length).map(t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + ')(?![A-Za-z])', 'gi');
const executiveMentions = (text, window = 120, limit = 8) => {
  const out = []; let lastEnd = -1, m;
  EXEC_TITLE_RE.lastIndex = 0;
  while ((m = EXEC_TITLE_RE.exec(text)) !== null && out.length < limit) {
    if (m.index < lastEnd) continue;
    const start = Math.max(0, m.index - window), end = Math.min(text.length, m.index + m[0].length + window);
    const snippet = text.slice(start, end).trim();
    if (!/[A-Z][a-z]+\s+[A-Z]/.test(snippet)) continue;      // no capitalised words nearby = a nav / heading mention
    out.push((start ? '…' : '') + snippet + (end < text.length ? '…' : ''));
    lastEnd = end;
  }
  return out.join(' | ');
};

// Executive messages are signed at the bottom, so the AI gets the head AND the tail of every page
const excerpt = (text, head, tail) => text.length <= head + tail ? text : `${text.slice(0, head)} … ${text.slice(-tail)}`;

const MAX_ONLINE_LOOKUPS = 20;   // per execution: LinkedIn / web searches for the decision maker when the site names nobody
let onlineLookups = 0;

// Why a site gave us nothing - shown in the Website Signals column and given to the AI
const PARKED = /defaultwebpage\.cgi|domain is parked|coming soon|under construction|index of \/|buy this domain|website is temporarily|account suspended/i;
const META_REFRESH = /<meta[^>]+http-equiv=["']?refresh["']?[^>]+content=["']?\s*\d+\s*;\s*url=([^"'>\s]+)/i;
const statusFromError = (msg) => {
  const m = String(msg || '');
  if (/ENOTFOUND|getaddrinfo|EAI_AGAIN/i.test(m)) return 'dns failure (domain no longer exists)';
  if (/403|401|429|503/.test(m)) return 'http ' + (m.match(/40[13]|429|503/) || ['403'])[0] + ' (blocks automated visits)';
  if (/50\d/.test(m)) return 'http ' + m.match(/50\d/)[0] + ' (server error)';
  if (/404/.test(m)) return 'http 404';
  if (/timeout|ETIMEDOUT|ECONNRESET|ECONNREFUSED/i.test(m)) return 'timeout';
  return m ? 'connection error (' + m.slice(0, 40) + ')' : 'no response';
};

const fetchPage = async (url) => (await fetchPageWithStatus(url)).html;
const fetchPageWithStatus = async (url, hops = 0) => {
  if (!http) return { html: '', status: 'no http helper', finalUrl: url };
  let body = '';
  try {
    const res = await http.httpRequest({
      url, method: 'GET', timeout: 8000, json: false, skipSslCertificateValidation: true,
      headers: { 'User-Agent': UA, 'Accept': 'text/html,*/*' }
    });
    body = typeof res === 'string' ? res : (res && typeof res.body === 'string') ? res.body : (res ? JSON.stringify(res) : '');
  } catch (e) {
    return { html: '', status: statusFromError(e && e.message), finalUrl: url };
  }
  const refresh = body.slice(0, 4000).match(META_REFRESH);
  if (refresh && body.length < 6000 && hops < 2) {                 // tiny page whose only job is to send visitors elsewhere
    let target;
    try { target = new URL(decodeEntities(refresh[1]), url).href; } catch (e) { target = ''; }
    if (target && !PARKED.test(target)) return fetchPageWithStatus(target, hops + 1);
  }
  if (PARKED.test(body.slice(0, 6000)) && body.length < 6000) return { html: '', status: 'parked / default page (site not live)', finalUrl: url };
  return { html: body, status: 'ok', finalUrl: url };
};

// When the company's own pages name nobody: LinkedIn profiles first ("Md. Hasan - Managing Director - Asgar Ali
// Hospital | LinkedIn"), then ordinary search snippets. Uses Bing's RSS feed, DuckDuckGo's HTML page as fallback.
const COMPANY_STOPWORDS = new Set(['hospital', 'hospitals', 'clinic', 'limited', 'ltd', 'centre', 'center', 'medical', 'diagnostic', 'general',
  'specialized', 'specialised', 'private', 'bangladesh', 'dhaka', 'college', 'plc', 'group', 'trust', 'foundation', 'health', 'care',
  'healthcare', 'international', 'research', 'institute', 'services', 'pharma', 'pharmaceuticals']);
const LINKEDIN_TITLE = /^(.+?)\s+[-–|]\s+(.+?)\s+[-–|]\s+(.+?)\s*\|\s*LinkedIn/i;      // Name - Title - Company | LinkedIn
const LINKEDIN_AT = /^(.+?)\s+[-–]\s+(.+?)\s+(?:at|@)\s+(.+?)\s*(?:[-|]\s*LinkedIn)?$/i;   // Name - Title at Company
const rawSearch = async (query) => {
  const items = [];
  try {
    const rss = await fetchPage(`https://www.bing.com/search?q=${encodeURIComponent(query)}&format=rss&cc=BD&setlang=en`);
    const re = /<item>[\s\S]*?<title>([\s\S]*?)<\/title>[\s\S]*?<link>([\s\S]*?)<\/link>[\s\S]*?<description>([\s\S]*?)<\/description>/g;
    let m;
    while ((m = re.exec(rss)) !== null) items.push([htmlToText(m[1]), decodeEntities(m[2]).trim(), htmlToText(m[3])]);
  } catch (e) {}
  if (items.length) return items;
  try {
    const page = await fetchPage(`https://html.duckduckgo.com/html/?q=${encodeURIComponent(query)}`);
    const re = /<a[^>]*class="result__a"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>[\s\S]*?<a[^>]*class="result__snippet"[^>]*>([\s\S]*?)<\/a>/g;
    let m;
    while ((m = re.exec(page)) !== null) {
      let url = m[1].replace(/&amp;/g, '&').trim();
      if (url.startsWith('//')) url = 'https:' + url;
      try { url = new URL(url).searchParams.get('uddg') || url; } catch (e) {}
      items.push([htmlToText(m[2]), url, htmlToText(m[3])]);
    }
  } catch (e) {}
  return items;
};
const lookupOnline = async (company) => {
  const tokens = (company.toLowerCase().match(/[a-z]{4,}/g) || []).filter(w => !COMPANY_STOPWORDS.has(w)).slice(0, 3);
  if (!tokens.length) return null;
  const mentions = (text) => tokens.some(t => String(text || '').toLowerCase().includes(t));
  const queries = [`"${company}" (managing director OR chairman OR ceo) site:linkedin.com/in`, `"${company}" managing director OR chairman OR "chief executive"`];
  for (let step = 0; step < queries.length; step++) {
    for (const [title, url, snippet] of await rawSearch(queries[step])) {
      if (url.includes('linkedin.com/in/')) {
        const m = title.match(LINKEDIN_TITLE) || title.match(LINKEDIN_AT);
        const execTitle = m && (m[2].match(EXEC_TITLE_RE) || [])[0];
        if (m && execTitle && mentions(m[3])) return { name: m[1].trim(), title: execTitle, linkedin: url.split('?')[0], source: 'LinkedIn search result' };
      } else if (step === 1 && mentions(title + ' ' + snippet)) {
        const hit = (title + '. ' + snippet).match(/([A-Z][\w.'-]*(?:\s+[A-Z][\w.'-]*){1,4}),?\s+(?:the\s+)?(Managing Director|Chairman|Chief Executive Officer|CEO|Executive Director|Medical Director)/);
        if (hit) return { name: hit[1].trim(), title: hit[2], linkedin: '', source: 'search snippet' };
      }
    }
  }
  return null;
};

const items = $input.all();
const out = new Array(items.length);

for (let start = 0; start < items.length; start += CONCURRENCY) {
  await Promise.all(items.slice(start, start + CONCURRENCY).map(async (item, offset) => {
    const i = start + offset;
    const lead = (leads[i] && leads[i].json) || {};
    let homepageHtml = typeof item.json.data === 'string' ? item.json.data : '';
    const fetchError = item.json.error ? String(item.json.error.message || item.json.error) : '';
    let siteStatus = homepageHtml ? 'ok' : statusFromError(fetchError);
    let siteUrl = lead.url || '';
    if (homepageHtml && homepageHtml.length < 6000 && (META_REFRESH.test(homepageHtml.slice(0, 4000)) || PARKED.test(homepageHtml))) {
      const followed = await fetchPageWithStatus(siteUrl);          // node 7 does not follow meta-refresh redirects
      homepageHtml = followed.html; siteStatus = followed.status;
      if (followed.html && followed.finalUrl !== siteUrl) { siteStatus = 'ok (redirects to ' + followed.finalUrl.replace(/^https?:\/\/(www\.)?/, '').split('/')[0] + ')'; siteUrl = followed.finalUrl; }
    }

    const extraUrls = (http && homepageHtml) ? findExtraLinks(homepageHtml, siteUrl) : [];
    const extraHtml = await Promise.all(extraUrls.map(fetchPage));

    const allHtml = [homepageHtml, ...extraHtml].join('\n');
    const fullText = [homepageHtml, ...extraHtml].filter(Boolean).map(htmlToText).join('\n');
    const signals = extractSignals(allHtml);
    const website = extractWebsiteSignals(allHtml, siteUrl);
    if (!homepageHtml) website.summary = 'website: ' + siteStatus;      // tells the reader WHY there is no page evidence
    const mentionsText = executiveMentions(fullText);
    let lookup = null;
    if (!mentionsText && http && onlineLookups < MAX_ONLINE_LOOKUPS) { onlineLookups++; lookup = await lookupOnline(lead.title || ''); }

    const sections = [];
    if (homepageHtml) sections.push('[Homepage] ' + excerpt(htmlToText(homepageHtml), 2000, 400));
    extraUrls.forEach((u, k) => { if (extraHtml[k]) sections.push('[' + u + '] ' + excerpt(htmlToText(extraHtml[k]), 900, 600)); });

    out[i] = {
      json: {
        company_url: siteUrl,                                      // the final site after redirects
        site_status: siteStatus,
        company_domain: lead.domain || '',
        search_title: lead.title || 'Dhaka Healthcare Facility',
        search_snippet: lead.snippet || '',
        scraped_text: sections.join('\n\n') || lead.snippet || '',
        pages_fetched: [homepageHtml ? siteUrl : '', ...extraUrls.filter((u, k) => extraHtml[k])].filter(Boolean).join(', '),
        found_emails: signals.emails.join(', '),
        found_phones: signals.phones.join(', '),
        found_linkedin: signals.linkedin.join(', '),
        found_facebook: signals.facebook.join(', '),
        fetch_error: fetchError,
        website_signals: website.summary,
        executive_mentions: mentionsText,
        online_lookup: lookup ? `${lookup.name} - ${lookup.title} (${lookup.source}) ${lookup.linkedin}`.trim() : '',
        online_lookup_linkedin: lookup ? lookup.linkedin : '',
        features_present: website.present.join(', '),
        features_missing: website.missing.join(', '),
        // Structured facts that came with the candidate (OpenStreetMap) - reused by the AI prompt and as fallbacks in node 11
        source: lead.source || 'web search',
        known_type: lead.known_type || '',
        known_location: lead.known_location || '',
        known_address: lead.known_address || '',
        known_phone: lead.known_phone || '',
        known_email: lead.known_email || '',
        known_facts: [
          lead.known_address && 'address: ' + lead.known_address,
          lead.known_phone && 'phone: ' + lead.known_phone,
          lead.known_email && 'email: ' + lead.known_email
        ].filter(Boolean).join('; ')
      },
      pairedItem: { item: i }
    };
  }));
}

return out;

