// Runs once for all items. Nodes 8, 9 and 10 each emit exactly one item per lead (errors included,
// because they continue on error), so the three arrays line up by index.
const companies = $('8. Extract Page Text & Contact Signals').all();
const extractions = $('9. OpenAI Decision Maker Extractor').all();
const emails = $input.all();

const parseChoice = (item) => {
  try {
    return JSON.parse(item.json.choices[0].message.content) || {};
  } catch (e) {
    return {};
  }
};

const clean = (v) => {
  if (v == null) return '';
  const s = Array.isArray(v) ? v.join('; ') : String(v).trim();
  return /^(n\/a|none|null|unknown|not available|not found|-)$/i.test(s) ? '' : s;
};

// 'Green Life Hospital Ltd | Best Hospital in Dhaka' -> 'Green Life Hospital Ltd' (search titles carry SEO tails)
const GENERIC_SEGMENT = /^(?:home(?:page)?|welcome(?: to)?|contact(?: us)?|about(?: us)?|services|login|official website)$/i;
const SEO_SEGMENT = /^(?:the\s+)?(?:best|top|leading|no\.?\s*1|number one|#1)\b/i;
const cleanCompanyName = (title, domain) => {
  const segments = String(title || '').split(/\s+[|\-–—:]\s+|\s*\|\s*/).filter(s => s.trim());
  for (let segment of segments) {
    segment = segment.replace(/^(?:home|welcome to|official website of)\s*[-:|]?\s*/i, '').trim();
    if (segment.length >= 3 && !GENERIC_SEGMENT.test(segment) && !SEO_SEGMENT.test(segment)) return segment;
  }
  const label = String(domain || '').split('.')[0];
  if (label.length >= 4) return label.replace(/[-_]/g, ' ').replace(/\b\w/g, c => c.toUpperCase());   // every segment was an SEO tagline
  return (segments[0] || String(title || '')).trim();
};

// '01712-345 678' -> '+8801712345678', '02-9612345' -> '+88029612345'; short hotlines (10606) are kept
const normalizeBdPhone = (raw) => {
  let digits = String(raw || '').replace(/\D/g, '');
  if (!digits) return String(raw || '').trim();
  if (digits.startsWith('00880')) digits = digits.slice(2);
  if (digits.startsWith('880') && digits.length >= 11) return '+' + digits;
  if (digits.startsWith('0') && [9, 10, 11].includes(digits.length)) return '+880' + digits.slice(1);
  if (digits.length <= 6) return digits;
  return String(raw || '').trim();
};
const normalizePhones = (value) => [...new Set(String(value || '').split(/[,;/|]|\s{2,}|\band\b/).filter(p => p.trim()).map(normalizeBdPhone))].join(', ');

// Telegram alert is sent in HTML parse mode, so escape anything that could be read as a tag
const esc = (v) => String(v == null ? '' : v)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');
const line = (label, value) => value ? `${label} ${esc(value)}\n` : '';

return emails.map((emailItem, i) => {
  const company = (companies[i] && companies[i].json) || {};
  const extracted = extractions[i] ? parseChoice(extractions[i]) : {};
  const email = parseChoice(emailItem);

  const lead = {
    "Company Name": clean(extracted.company_name) || cleanCompanyName(company.search_title, company.company_domain) || 'Unknown',
    "Healthcare Type": clean(extracted.healthcare_type) || company.known_type || '',
    "Dhaka Location": clean(extracted.dhaka_location) || company.known_location || '',
    "Full Address": clean(extracted.full_address) || company.known_address || '',
    "Website": company.company_url || '',
    "Phone": normalizePhones(clean(extracted.contact_phone) || company.known_phone || clean(company.found_phones).split(',')[0].trim()),
    "Generic Email": clean(extracted.generic_email) || company.known_email || clean(company.found_emails).split(',')[0].trim(),
    "Facebook Page": clean(extracted.facebook_page) || clean(company.found_facebook).split(',')[0].trim(),
    "Key Services": clean(extracted.key_services),
    "Fit Score": clean(extracted.fit_score),
    "Fit Reason": clean(extracted.fit_reason),
    "Website Signals": company.website_signals || '',
    "Decision Maker Name": clean(extracted.decision_maker_name),
    "Decision Maker Title": clean(extracted.decision_maker_title),
    "Decision Maker Email": clean(extracted.decision_maker_email),
    "Decision Maker Phone": normalizePhones(clean(extracted.decision_maker_phone)),
    "Decision Maker LinkedIn": clean(extracted.decision_maker_linkedin) || company.online_lookup_linkedin || clean(company.found_linkedin).split(',')[0].trim(),
    "Other Decision Makers": clean(extracted.other_decision_makers),
    "Email Subject": clean(email.subject_line),
    "Personalized Hook": clean(email.personalized_hook),
    "Personalized Email": clean(email.email_body),
    "Timestamp": new Date().toISOString(),
    // not sheet columns (node 12 maps columns explicitly) - used by nodes 12b and 14
    "_source": company.source || 'web search',
    "_fit": parseInt(clean(extracted.fit_score), 10) || 0
  };

  lead["Telegram Message"] =
    `🏥 <b>NEW DHAKA HEALTHCARE LEAD</b>\n\n` +
    line('🏢 <b>Company:</b>', lead["Company Name"]) +
    line('🏷 <b>Type:</b>', lead["Healthcare Type"]) +
    line('📍 <b>Location:</b>', lead["Dhaka Location"]) +
    line('🏠 <b>Address:</b>', lead["Full Address"]) +
    line('🌐 <b>Website:</b>', lead["Website"]) +
    line('📞 <b>Phone:</b>', lead["Phone"]) +
    line('📧 <b>Email:</b>', lead["Generic Email"]) +
    line('📘 <b>Facebook:</b>', lead["Facebook Page"]) +
    line('🩺 <b>Services:</b>', lead["Key Services"]) +
    line('🎯 <b>Offer fit:</b>', lead["Fit Score"] ? lead["Fit Score"] + '/5 - ' + lead["Fit Reason"] : '') +
    `\n👑 <b>DECISION MAKER</b>\n` +
    line('👤 <b>Name:</b>', lead["Decision Maker Name"] || 'Not found on site') +
    line('💼 <b>Title:</b>', lead["Decision Maker Title"]) +
    line('📧 <b>Direct Email:</b>', lead["Decision Maker Email"]) +
    line('📱 <b>Direct Phone:</b>', lead["Decision Maker Phone"]) +
    line('🔗 <b>LinkedIn:</b>', lead["Decision Maker LinkedIn"]) +
    line('👥 <b>Others:</b>', lead["Other Decision Makers"]) +
    `\n` +
    line('✉️ <b>Draft Subject:</b>', lead["Email Subject"]) +
    line('💡 <b>Hook:</b>', lead["Personalized Hook"]) +
    `\n<i>Saved to Google Sheets pipeline.</i>`;

  return { json: lead, pairedItem: { item: i } };
});

// Only leads with Fit Score >= MIN_FIT_ALERT (node 0) get an individual Telegram alert; every lead is still saved to
// the sheet and counted in the run summary. With MIN_FIT_ALERT = 0 all leads are alerted.
const minFit = $('0. Offer Profile').first().json.minFitAlert || 0;
return $input.all()
  .map((item, i) => ({ json: item.json, pairedItem: { item: i } }))
  .filter(item => !minFit || (item.json._fit && item.json._fit >= minFit));

// Runs once with every formatted lead of this execution and builds one Telegram message: what the run produced,
// where the leads came from, how they scored against the offer and which ones to call first.
const leads = $input.all().map(i => i.json);
const n = leads.length;
// The two numbers a manager asks for: hours of manual research replaced and what the AI cost
const MANUAL_MINUTES_PER_LEAD = 25;   // find the company, its decision maker, contacts, write a tailored email - by hand
const AI_COST_PER_LEAD_USD = 0.004;   // two gpt-4o-mini calls with the offer brief in the prompt (estimate)
const hours = (n * MANUAL_MINUTES_PER_LEAD / 60).toFixed(1);
const cost = (n * AI_COST_PER_LEAD_USD).toFixed(2);
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const sources = {};
for (const l of leads) sources[l._source || 'web search'] = (sources[l._source || 'web search'] || 0) + 1;
const sourceLine = Object.entries(sources).sort((a, b) => b[1] - a[1]).map(([s, c]) => `${s} ${c}`).join(' · ');

const fits = leads.map(l => l._fit || 0);
const count = (v) => fits.filter(f => f === v).length;
const low = fits.filter(f => f > 0 && f <= 2).length;
const fitParts = [5, 4, 3].filter(count).map(v => `${v}★ ${count(v)}`);
if (low) fitParts.push(`≤2★ ${low}`);
if (count(0)) fitParts.push(`unrated ${count(0)}`);
const fitLine = fitParts.join(' · ') || 'no offer brief';

const dm = leads.filter(l => l["Decision Maker Name"]).length;
const dmEmail = leads.filter(l => l["Decision Maker Email"]).length;
const phone = leads.filter(l => l["Phone"]).length;
const email = leads.filter(l => l["Generic Email"]).length;
const top = leads.filter(l => (l._fit || 0) >= 4).sort((a, b) => b._fit - a._fit).slice(0, 5);

const lines = [
  `📊 <b>RUN SUMMARY</b> - ${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC`,
  `✅ <b>${n} new leads</b> saved to Google Sheets`,
  `📡 Sources: ${esc(sourceLine || '-')}`,
  `🎯 Offer fit: ${esc(fitLine)}`,
  `👑 Decision maker found: ${dm}/${n} · direct email ${dmEmail} · phone ${phone} · email ${email}`,
  `⏱ Manual research replaced: ~${hours} h (${n} × ${MANUAL_MINUTES_PER_LEAD} min) · 💰 AI cost: ~$${cost}`
];
if (top.length) {
  lines.push('', '🔥 <b>Top fits</b>');
  top.forEach((l, i) => {
    lines.push(`${i + 1}. <b>${esc(l["Company Name"])}</b> - ${l._fit}/5` +
      (l["Decision Maker Name"] ? ` - ${esc(l["Decision Maker Name"])} (${esc(l["Decision Maker Title"] || '?')})` : ''));
    if (l["Fit Reason"]) lines.push(`   <i>${esc(String(l["Fit Reason"]).slice(0, 120))}</i>`);
  });
}
if (!n) lines.push('', '⚠️ No new leads this run - every candidate was already in the sheet or the sources were throttled. Widen areas / categories or the OpenStreetMap bounding box.');

return [{ json: { summary: lines.join('\n'), leads: n, decision_makers: dm, sources, fit_distribution: { 5: count(5), 4: count(4), 3: count(3), low, unrated: count(0) }, hours_saved: Number(hours), ai_cost_usd: Number(cost) } }];
